# RWDM_ISOLATE: Isolate and Unisolate: hide everything except the selection, then restore. The script rwdm_isolate_script.txt is generated by rwdm_gen.py. The oracle is exact set logic on four Point objects (ids 1..4 at x = 1..4):
# each step lists the objects that a SelAll (or the current selection) reaches, and the ids must equal the expected set exactly (and the count line must agree).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_ISOLATE_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_isolate_script.txt" 2>&1)" || { echo "$RWDM_ISOLATE_OUT" | tail -40; echo "FAIL RWDM_ISOLATE_run: script exited non-zero"; fail=1; RWDM_ISOLATE_OUT=""; }
else
  RWDM_ISOLATE_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_isolate_script.txt" 2>&1)" || { echo "$RWDM_ISOLATE_OUT" | tail -40; echo "FAIL RWDM_ISOLATE_run: script exited non-zero"; fail=1; RWDM_ISOLATE_OUT=""; }
fi
rwdm_isolate_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_ISOLATE_OUT"; }
# rwdm_isolate_ids STEP EXPECTED_IDS COUNT_LINE_OR_NONE DESC: the ids listed in the step, in order, are exactly EXPECTED_IDS ("-" = none); COUNT: the "N object(s) selected" line must say N
rwdm_isolate_ids() {
  local blk got cnt; blk="$(rwdm_isolate_block "$1")"
  got="$({ grep -oE '^history: Object [0-9]+ ' <<<"$blk" || true; } | sed -E 's/^history: Object ([0-9]+) /\1/' | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  cnt="$({ grep -oE '^history: [0-9]+ object\(s\) selected' <<<"$blk" || true; } | tail -1 | sed -E 's/^history: ([0-9]+) .*/\1/')"
  if [ "$got" = "$2" ] && { [ "$3" = none ] || [ "$cnt" = "$3" ]; }; then echo "ok   RWDM_ISOLATE_$1: $4 (ids: $got)"
  else echo "FAIL RWDM_ISOLATE_$1: $4 (listed ids '$got', expected '$2'; selected-count line '${cnt:-none}', expected '$3')"; fail=1; fi
}
rwdm_isolate_ids isolate "4" 1 "Isolate with 4 selected leaves only object 4 visible"
rwdm_isolate_ids unisolate "1 2 3 4" 4 "Unisolate shows what Isolate hid: all four visible again"
rwdm_isolate_ids isolate2 "2 3" 2 "Isolate with 2 and 3 selected leaves exactly 2 and 3 visible"
rwdm_isolate_ids unisolate2 "1 2 3 4" 4 "a second Unisolate restores 1 and 4 as well"
